const crypto = require('crypto');
const now = new Date().toISOString();
// Multipart text fields arrive as raw strings under json.body.<field> - the UI
// sends one field, 'params', holding the whole config as a JSON string.
const body = JSON.parse($input.item.json.body.params);
const jobId = crypto.randomUUID();

const pdfMeta = (body.pdfs || []).map((p, i) => ({
  id: `pdf-${i + 1}`,
  filename: p.filename,
  path: `data/jobs/${jobId}/input/pdf-${i + 1}.pdf`,
  role: p.role,
  order: p.order ?? i,
  binaryKey: p.binaryKey
}));

const job = {
  jobId,
  createdAt: now,
  updatedAt: now,
  phase: 'prepare',
  step: 'saving_inputs',
  error: null,
  params: {
    targetDurationSeconds: body.targetDurationSeconds,
    narrationStyle: body.narrationStyle || '',
    voice: {
      mode: body.voice.mode,
      presetVoiceId: body.voice.presetVoiceId || null,
      customDescription: body.voice.customDescription || null,
      resolvedVoiceId: null
    },
    transition: {
      type: body.transition.type,
      transitionSeconds: body.transition.transitionSeconds ?? 0.75,
      minSlideSeconds: body.transition.minSlideSeconds ?? 3.0
    },
    aspectRatio: body.aspectRatio || '16:9',
    resolution: body.resolution || '1920x1080',
    captions: !!body.captions
  },
  sources: {
    srt: {
      filename: body.srtFilename,
      path: `data/jobs/${jobId}/input/transcript.srt`,
      cueCount: null,
      durationSeconds: null,
      fullText: null
    },
    pdfs: pdfMeta
  },
  slides: [],
  alignment: [],
  narration: [],
  audio: [],
  render: { renderedAt: null, outputPath: null, outputUrl: null, renderCount: 0 },
  manus: { taskId: null, status: null }
};

return [{ json: { job }, binary: $input.item.binary }];

const job = $('Build Job Record').item.json.job;
const binary = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(job, null, 2)), 'job.json', 'application/json');
return [{ json: { job, jobJsonPath: `data/jobs/${job.jobId}/job.json` }, binary: { jobJson: binary } }];

const job = $('Build Job Record').item.json.job;
const binary = $('Build Job Record').item.binary;

const files = [
  { targetPath: job.sources.srt.path, binaryKey: 'srt' },
  ...job.sources.pdfs.map(p => ({ targetPath: p.path, binaryKey: p.binaryKey }))
];

return files.map(f => ({ json: { targetPath: f.targetPath }, binary: { data: binary[f.binaryKey] } }));

const buf = await this.helpers.binaryToBuffer($('Build Job Record').item.binary.srt);
const text = buf.toString('utf-8');

const cues = [];
const blocks = text.replace(/\r/g, '').split(/\n\n+/).filter(Boolean);
for (const block of blocks) {
  const lines = block.split('\n');
  const timeLine = lines.find(l => l.includes('-->'));
  if (!timeLine) continue;
  const textLines = lines.slice(lines.indexOf(timeLine) + 1);
  cues.push({ time: timeLine.trim(), text: textLines.join(' ').trim() });
}

const fullText = cues.map(c => c.text).join(' ');
const toSeconds = (t) => {
  const [h, m, s] = t.split(':');
  const [sec, ms] = s.split(',');
  return (+h) * 3600 + (+m) * 60 + (+sec) + (+ms) / 1000;
};
const lastCue = cues[cues.length - 1];
const durationSeconds = lastCue ? toSeconds(lastCue.time.split(' --> ')[1]) : 0;

const job = $('Build Job Record').item.json.job;
job.sources.srt.cueCount = cues.length;
job.sources.srt.durationSeconds = durationSeconds;
job.sources.srt.fullText = fullText;
job.step = 'extracting_pdfs';
job.updatedAt = new Date().toISOString();

return [{ json: { job } }];

const job = $('Parse SRT').item.json.job;
const jobDir = `data/jobs/${job.jobId}`;

const parts = job.sources.pdfs.map(pdf => `
pdf="${pdf.path}"
prefix="${jobDir}/slides/${pdf.id}-p"
pages=$(pdfinfo "$pdf" | awk '/^Pages:/{print $2}')
pdftoppm -png -r 150 "$pdf" "$prefix"
for i in $(seq 1 "$pages"); do
  pnum=$(printf "%03d" "$i")
  pdftotext -layout -f "$i" -l "$i" "$pdf" "${prefix}${pnum}.txt"
done`.trim());

return [{ json: { job, command: parts.join('\n') } }];

const job = $('Parse SRT').item.json.job;
const stdout = $input.item.json.stdout || '';
const files = stdout.split('\n').map(l => l.trim()).filter(Boolean);

const slides = files.map(pngPath => {
  const match = pngPath.match(/\/(pdf-\d+)-p0*(\d+)\.png$/);
  if (!match) return null;
  const [, pdfId, pageNumStr] = match;
  const pageNumber = parseInt(pageNumStr, 10);
  const pnum = String(pageNumber).padStart(3, '0');
  return {
    slideId: `${pdfId}-p${pnum}`,
    pdfId,
    pageNumber,
    imagePath: pngPath,
    textPath: pngPath.replace(/-p0*\d+\.png$/, `-p${pnum}.txt`),
    manusFileId: null
  };
}).filter(Boolean)
  .sort((a, b) => (a.pdfId === b.pdfId ? a.pageNumber - b.pageNumber : a.pdfId.localeCompare(b.pdfId)));

job.slides = slides;
job.step = 'uploading_slides_to_manus';
job.updatedAt = new Date().toISOString();

return [{ json: { job } }];

const job = $('Build Slides Index').item.json.job;
const binary = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(job, null, 2)), 'job.json', 'application/json');
return [{ json: { job, jobJsonPath: `data/jobs/${job.jobId}/job.json` }, binary: { jobJson: binary } }];

const job = $('Build Slides Index').item.json.job;
const results = $input.all();
const idBySlide = {};
for (const r of results) idBySlide[r.json.slideId] = r.json.file_id;
job.slides = job.slides.map(s => ({ ...s, manusFileId: idBySlide[s.slideId] ?? null }));
job.step = 'aligning';
job.updatedAt = new Date().toISOString();
return [{ json: { job } }];

const job = $('Collect Manus File Ids').item.json.job;
const schema = {
  type: 'object',
  properties: {
    alignment: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          slide_id: { type: 'string' },
          transcript_excerpt: { type: 'string' },
          confidence: { type: 'number' },
          notes: { type: 'string' }
        },
        required: ['slide_id', 'transcript_excerpt']
      }
    }
  },
  required: ['alignment']
};

const slideMeta = job.slides.map(s => ({ slide_id: s.slideId, pdf_role: job.sources.pdfs.find(p => p.id === s.pdfId)?.role }));
const prompt = `You are aligning a video transcript to presentation slide images.\n\nSlide images are attached in the order listed below, each tagged 'primary' or 'supplementary' by source deck. Build the main narrative sequence from the primary deck; pull a slide from a supplementary deck only when it covers transcript content the primary deck does not show. Skip slides (title/agenda/blank) that have no corresponding narrated content.\n\nFull transcript:\n${job.sources.srt.fullText}\n\nSlide order and role metadata:\n${JSON.stringify(slideMeta)}\n\nReturn, in narrative order, which slides correspond to which excerpt of the transcript.`;

return [{ json: {
  job,
  body: {
    message: prompt,
    attachments: job.slides.map(s => ({ file_id: s.manusFileId })),
    structured_output_schema: schema
  }
} }];

const job = $('Collect Manus File Ids').item.json.job;
job.manus.taskId = $input.item.json.task_id;
job.manus.status = $input.item.json.status || 'running';
job.step = 'aligning';
job.updatedAt = new Date().toISOString();
const binary = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(job, null, 2)), 'job.json', 'application/json');
return [{ json: { job, jobJsonPath: `data/jobs/${job.jobId}/job.json` }, binary: { jobJson: binary } }];

const job = $('Collect Manus File Ids').item.json.job;
const resp = $input.item.json;
job.manus.status = resp.agent_status || resp.status;
job.alignment = (resp.structured_output?.alignment || []).map((a, i) => ({
  sequenceIndex: i,
  slideId: a.slide_id,
  transcriptExcerpt: a.transcript_excerpt,
  confidence: a.confidence ?? null,
  notes: a.notes || ''
}));
job.step = 'condensing_narration';
job.updatedAt = new Date().toISOString();
return [{ json: { job } }];

const job = $('Parse Alignment Result').item.json.job;
const binary = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(job, null, 2)), 'job.json', 'application/json');
return [{ json: { job, jobJsonPath: `data/jobs/${job.jobId}/job.json` }, binary: { jobJson: binary } }];

const job = $('Parse Alignment Result').item.json.job;
const totalChars = job.alignment.reduce((sum, a) => sum + a.transcriptExcerpt.length, 0) || 1;
const totalWordBudget = Math.round(job.params.targetDurationSeconds / 60 * 130);
const segments = job.alignment.map(a => ({
  sequenceIndex: a.sequenceIndex,
  slideId: a.slideId,
  excerpt: a.transcriptExcerpt,
  wordBudget: Math.max(5, Math.round((a.transcriptExcerpt.length / totalChars) * totalWordBudget))
}));

const styleInstruction = job.params.narrationStyle || 'clear, neutral documentary narration';
const prompt = `Condense each transcript excerpt below into narration matching this style: "${styleInstruction}".\nTotal narration across all segments must sum to about ${totalWordBudget} words (~${job.params.targetDurationSeconds}s spoken at 130wpm).\nEach segment lists its own word budget; stay close to it while keeping sentences natural and self-contained (each plays over one static image).\nRespond with ONLY JSON of the shape {"narration":[{"sequence_index":0,"slide_id":"...","script":"..."}]}.\n\nSegments:\n${JSON.stringify(segments, null, 2)}`;

return [{ json: { job, prompt } }];

const job = $('Parse Alignment Result').item.json.job;
const raw = $input.item.json;
const text = raw.content?.[0]?.text || '{"narration":[]}';
let parsed;
try { parsed = JSON.parse(text); } catch (e) { parsed = { narration: [] }; }

job.narration = parsed.narration.map(n => {
  const words = (n.script || '').trim().split(/\s+/).filter(Boolean).length;
  return {
    sequenceIndex: n.sequence_index,
    slideId: n.slide_id,
    script: n.script,
    estimatedWords: words,
    estimatedSeconds: Math.round((words / 130) * 60)
  };
}).sort((a, b) => a.sequenceIndex - b.sequenceIndex);

job.step = 'resolving_voice';
job.updatedAt = new Date().toISOString();
return [{ json: { job } }];

const job = $('Parse Narration Result').item.json.job;
const binary = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(job, null, 2)), 'job.json', 'application/json');
return [{ json: { job, jobJsonPath: `data/jobs/${job.jobId}/job.json` }, binary: { jobJson: binary } }];

const job = $('Parse Narration Result').item.json.job;
job.params.voice.resolvedVoiceId = $input.item.json.voice_id;
job.step = 'synthesizing_audio';
job.updatedAt = new Date().toISOString();
return [{ json: { job } }];

const job = $('Parse Narration Result').item.json.job;
job.params.voice.resolvedVoiceId = job.params.voice.presetVoiceId;
job.step = 'synthesizing_audio';
job.updatedAt = new Date().toISOString();
return [{ json: { job } }];

const job = $('Merge Voice Branch').item.json.job;
const binary = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(job, null, 2)), 'job.json', 'application/json');
return [{ json: { job, jobJsonPath: `data/jobs/${job.jobId}/job.json` }, binary: { jobJson: binary } }];

const seg = $('Narration To Items').item.json.seg;
const jobId = $('Narration To Items').item.json.job.jobId;
const stdout = $input.item.json.stdout;
let durationSeconds = 0;
try { durationSeconds = parseFloat(JSON.parse(stdout).format.duration); } catch (e) {}
const pnum = String(seg.sequenceIndex).padStart(3, '0');
return { json: {
  sequenceIndex: seg.sequenceIndex,
  path: `data/jobs/${jobId}/audio/seg-${pnum}.mp3`,
  durationSeconds
} };

const job = $('Merge Voice Branch').item.json.job;
const items = $input.all();
job.audio = items.map(i => i.json).sort((a, b) => a.sequenceIndex - b.sequenceIndex);
job.phase = 'ready_for_render';
job.step = 'ready_for_render';
job.updatedAt = new Date().toISOString();
return [{ json: { job } }];

const job = $('Collect Audio Durations').item.json.job;
const binary = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(job, null, 2)), 'job.json', 'application/json');
return [{ json: { job, jobJsonPath: `data/jobs/${job.jobId}/job.json` }, binary: { jobJson: binary } }];
